// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract PublicLedger {
    
    // Define the structure of a Project on the blockchain
    struct Project {
        uint256 id;
        string title;
        uint256 budget;
        address officer;
        bool fundsReleased;
        bool exists;
    }

    // A mapping to store projects by their ID
    mapping(uint256 => Project) public projects;

    // Events to log activity (this creates the "Transaction Hash")
    event ProjectCreated(uint256 id, string title, uint256 budget, address officer);
    event FundsReleased(uint256 id, uint256 amount, address officer);

    // Function 1: Create a Project
    // This locks the details on the blockchain
    function createProject(uint256 _id, string memory _title, uint256 _budget) public {
        require(!projects[_id].exists, "Project ID already exists");
        
        projects[_id] = Project({
            id: _id,
            title: _title,
            budget: _budget,
            officer: msg.sender,
            fundsReleased: false,
            exists: true
        });

        emit ProjectCreated(_id, _title, _budget, msg.sender);
    }

    // Function 2: Verify & Release Funds
    // This is the critical "Audit" function
    function verifyAndRelease(uint256 _id) public {
        require(projects[_id].exists, "Project does not exist");
        require(!projects[_id].fundsReleased, "Funds already released");

        // Mark as released
        projects[_id].fundsReleased = true;
        
        // Emit event to prove it happened
        emit FundsReleased(_id, projects[_id].budget, projects[_id].officer);
    }
}

